import{_ as h,o as a,c as t,a3 as i}from"./chunks/framework.DX_KL3e0.js";const d=JSON.parse('{"title":"Văn Bản - Quyết Định","description":"","frontmatter":{},"headers":[],"relativePath":"chuc-nang/van-ban-quyet-dinh.md","filePath":"chuc-nang/van-ban-quyet-dinh.md","lastUpdated":1782639524000}'),c={name:"chuc-nang/van-ban-quyet-dinh.md"};function l(o,n,e,u,r,g){return a(),t("div",null,[...n[0]||(n[0]=[i('<h1 id="van-ban-quyet-đinh" tabindex="-1">Văn Bản - Quyết Định <a class="header-anchor" href="#van-ban-quyet-đinh" aria-label="Permalink to &quot;Văn Bản - Quyết Định&quot;">​</a></h1><p>Phân hệ <strong>Văn Bản - Quyết Định</strong> là nơi lưu và tra cứu các văn bản nội bộ như quyết định, thông báo, quy định hoặc tài liệu ban hành chính thức.</p><div class="info custom-block"><p class="custom-block-title">Tóm tắt nhanh</p><ul><li><strong>Đường dẫn:</strong> <code>/tra-cuu/van-ban</code>.</li><li><strong>Ai dùng được:</strong> người dùng có quyền xem văn bản; quyền thêm/sửa/xóa phụ thuộc phân quyền.</li><li><strong>Dùng để:</strong> lưu trữ, tìm kiếm, mở chi tiết và tải tài liệu ban hành nội bộ.</li></ul></div><h2 id="giao-dien-chinh" tabindex="-1">Giao diện chính <a class="header-anchor" href="#giao-dien-chinh" aria-label="Permalink to &quot;Giao diện chính&quot;">​</a></h2><p>Trang gồm các khu vực chính:</p><ul><li>Danh sách văn bản ở bên trái hoặc vùng danh sách.</li><li>Khung chi tiết văn bản đang chọn.</li><li>Bộ lọc và ô tìm kiếm để lọc theo tên, số văn bản hoặc loại văn bản.</li><li>Nút thêm mới nếu tài khoản có quyền quản trị nội dung.</li></ul><h2 id="cac-thao-tac-chinh" tabindex="-1">Các thao tác chính <a class="header-anchor" href="#cac-thao-tac-chinh" aria-label="Permalink to &quot;Các thao tác chính&quot;">​</a></h2><h3 id="tim-van-ban" tabindex="-1">Tìm văn bản <a class="header-anchor" href="#tim-van-ban" aria-label="Permalink to &quot;Tìm văn bản&quot;">​</a></h3><ol><li>Mở <code>/tra-cuu/van-ban</code>.</li><li>Nhập từ khóa vào ô tìm kiếm.</li><li>Lọc theo loại văn bản nếu cần.</li><li>Chọn một mục trong danh sách để xem chi tiết.</li></ol><h3 id="xem-chi-tiet" tabindex="-1">Xem chi tiết <a class="header-anchor" href="#xem-chi-tiet" aria-label="Permalink to &quot;Xem chi tiết&quot;">​</a></h3><p>Chi tiết thường gồm:</p><ul><li>Tên văn bản</li><li>Số văn bản</li><li>Loại văn bản</li><li>Đơn vị ban hành</li><li>Ngày ban hành</li><li>Mô tả hoặc nội dung tóm tắt</li><li>Tệp đính kèm nếu có</li></ul><h3 id="them-van-ban-moi" tabindex="-1">Thêm văn bản mới <a class="header-anchor" href="#them-van-ban-moi" aria-label="Permalink to &quot;Thêm văn bản mới&quot;">​</a></h3><ol><li>Nhấn <strong>Thêm mới</strong>.</li><li>Nhập các trường bắt buộc như tên văn bản và loại văn bản.</li><li>Điền số văn bản, ngày ban hành, đơn vị ban hành nếu có.</li><li>Đính kèm tệp liên quan.</li><li>Lưu lại để phát hành vào kho tra cứu.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Nên dùng tên văn bản nhất quán và có số hiệu rõ ràng để việc tìm kiếm sau này nhanh hơn.</p></div><h3 id="chinh-sua-hoac-cap-nhat" tabindex="-1">Chỉnh sửa hoặc cập nhật <a class="header-anchor" href="#chinh-sua-hoac-cap-nhat" aria-label="Permalink to &quot;Chỉnh sửa hoặc cập nhật&quot;">​</a></h3><p>Người có quyền có thể mở văn bản rồi cập nhật lại nội dung mô tả, tệp đính kèm hoặc thông tin phát hành.</p><h2 id="khi-nao-nen-dung-phan-he-nay" tabindex="-1">Khi nào nên dùng phân hệ này <a class="header-anchor" href="#khi-nao-nen-dung-phan-he-nay" aria-label="Permalink to &quot;Khi nào nên dùng phân hệ này&quot;">​</a></h2><p>Dùng <strong>Văn Bản - Quyết Định</strong> cho các nội dung có tính chính thức, cần tra cứu lại về sau, ví dụ:</p><ul><li>quyết định nhân sự</li><li>quy định nội bộ</li><li>hướng dẫn vận hành</li><li>thông báo ban hành chính thức</li></ul><p>Nếu nội dung chỉ mang tính cập nhật nhanh hoặc truyền thông ngắn hạn, nên dùng <a href="/help/chuc-nang/thong-bao-truyen-thong.html">Thông Báo - Truyền Thông</a>.</p><h2 id="cau-hoi-thuong-gap" tabindex="-1">Câu hỏi thường gặp <a class="header-anchor" href="#cau-hoi-thuong-gap" aria-label="Permalink to &quot;Câu hỏi thường gặp&quot;">​</a></h2><p><strong>Tôi không thấy nút thêm văn bản?</strong><br> Tài khoản của bạn chưa có quyền tạo hoặc chỉnh sửa văn bản.</p><p><strong>Tôi nên đăng nội dung ở đây hay ở Thông Báo?</strong><br> Nếu nội dung cần lưu trữ chính thức và tra cứu lâu dài, dùng Văn Bản. Nếu là thông tin cập nhật nhanh, dùng Thông Báo.</p><hr><p><em>Liên quan:</em> <a href="/help/chuc-nang/tra-cuu.html">Tra cứu</a> · <a href="/help/chuc-nang/thong-bao-truyen-thong.html">Thông Báo - Truyền Thông</a></p>',26)])])}const b=h(c,[["render",l]]);export{d as __pageData,b as default};
